    for (let attempt = 0; 60 &gt; attempt; attempt++) {
        await new Promise(resolve =&gt; { setTimeout(resolve, 1000); });
        try {
            const response = await fetch(
                `${NODE_URL}/transactionStatus/${transactionHash}`);
